<script setup>
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue';
import { Cropper } from 'vue-advanced-cropper';
import 'vue-advanced-cropper/dist/style.css';
import { UploadCloud, ImagePlus, Crop, UserRound, Building2, ZoomIn, ZoomOut, RotateCcw, RotateCw, RefreshCw, Check, X, LoaderCircle, Trash2, Move } from 'lucide-vue-next';
import { useAuth } from '../composables/useAuth.js';
import { validateImageUpload, fitImageRect } from '../services/image-upload.js';
const props=defineProps({employeeId:Number,path:String,readonly:Boolean,resource:{type:String,default:'employees'},label:{type:String,default:'Employee photo'}});
const emit=defineEmits(['change','editing']);const {request:apiRequest}=useAuth();
const isLogo=computed(()=>props.resource==='shippers');const imageKind=computed(()=>isLogo.value?'logo':'photo');
const input=ref(null),preview=ref(''),source=ref(''),cropper=ref(null),error=ref(''),working=ref(false),ready=ref(false),dragging=ref(false),loading=ref(false);
const originalImage=shallowRef(null);let generation=0,request,hasDraft=false,disposed=false;
function revoke(url){if(url)URL.revokeObjectURL(url);}
watch(source,value=>emit('editing',!!value));
watch(()=>[props.employeeId,props.path],async()=>{
 if(hasDraft)return;const current=++generation;request?.abort();request=new AbortController();revoke(preview.value);preview.value='';revoke(source.value);source.value='';originalImage.value=null;error.value='';loading.value=false;
 if(props.employeeId&&props.path){loading.value=true;try{const blob=await apiRequest('/'+props.resource+'/'+props.employeeId+'/'+(isLogo.value?'logo':'photo'),{responseType:'blob',signal:request.signal});if(!disposed&&current===generation)preview.value=URL.createObjectURL(blob);}catch(failure){if(current===generation&&failure.name!=='AbortError')error.value='The saved image is unavailable. You can choose a replacement.';}finally{if(current===generation)loading.value=false;}}
},{immediate:true});
function startCrop(file){
 if(props.readonly||working.value)return;const message=validateImageUpload(file);if(message){error.value=message;return;}
 const url=URL.createObjectURL(file);const image=new Image();const current=++generation;request?.abort();loading.value=true;error.value='';
 image.onload=()=>{if(disposed||current!==generation){revoke(url);return;}loading.value=false;if(image.naturalWidth>8000||image.naturalHeight>8000){revoke(url);error.value='Choose an image no larger than 8000 pixels on either side.';return;}revoke(source.value);originalImage.value=image;ready.value=false;source.value=url;};
 image.onerror=()=>{revoke(url);if(!disposed&&current===generation){loading.value=false;error.value='This image could not be opened. Choose another JPG, PNG or WebP image.';}};image.src=url;
}
function choose(event){const file=event.target.files?.[0];event.target.value='';if(file)startCrop(file);}
function drop(event){dragging.value=false;if(props.readonly||working.value)return;const files=Array.from(event.dataTransfer?.files||[]);if(files.length!==1){error.value='Drop one image at a time.';return;}startCrop(files[0]);}
async function editExisting(){if(!preview.value||props.readonly)return;try{const file=await(await fetch(preview.value)).blob();startCrop(file);}catch{error.value='This image could not be opened for editing.';}}
function cancelCrop(){generation++;ready.value=false;loading.value=false;revoke(source.value);source.value='';originalImage.value=null;}
function moveWithKeyboard(event){const offsets={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]};if(!ready.value||working.value||!offsets[event.key])return;event.preventDefault();cropper.value?.move(...offsets[event.key]);}
async function useImage(full=false){
 if(working.value||props.readonly)return;working.value=true;error.value='';const current=generation;
 try{const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const context=canvas.getContext('2d');context.fillStyle='#ffffff';context.fillRect(0,0,512,512);
 if(full){const image=originalImage.value;if(!image)throw new Error();const rect=fitImageRect(image.naturalWidth,image.naturalHeight);context.drawImage(image,rect.x,rect.y,rect.width,rect.height);}
 else{const result=cropper.value?.getResult();if(!result?.canvas)throw new Error();context.drawImage(result.canvas,0,0,512,512);}
 const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));if(!blob)throw new Error();if(disposed||current!==generation)return;
 request?.abort();revoke(preview.value);preview.value=URL.createObjectURL(blob);hasDraft=true;emit('change',blob);cancelCrop();
 }catch{if(!disposed)error.value='The image could not be prepared. Reset the crop or choose another image.';}finally{if(!disposed)working.value=false;}
}
function remove(){if(props.readonly||working.value)return;hasDraft=true;request?.abort();revoke(preview.value);preview.value='';cancelCrop();error.value='';emit('change',null);}
onBeforeUnmount(()=>{disposed=true;generation++;request?.abort();revoke(source.value);revoke(preview.value);});
</script>
<template>
 <section class="employee-photo-editor friendly-image-upload" :aria-label="label">
  <div class="photo-summary"><div class="employee-photo" :class="{'company-logo-preview':isLogo}"><LoaderCircle v-if="loading&&!source" class="spin" :size="24"/><img v-else-if="preview" :src="preview" :alt="label"/><Building2 v-else-if="isLogo" :size="30"/><UserRound v-else :size="30"/></div><div><h3>{{label}}</h3><p>{{readonly?'':preview?'Your image is ready. Save the form to keep any changes.':'Add a clear image to personalize this profile.'}}</p><div v-if="!readonly&&preview&&!source" class="photo-buttons"><button type="button" class="text-btn" @click="input.click()"><ImagePlus :size="14"/>Replace</button><button type="button" class="text-btn" @click="editExisting"><Crop :size="14"/>Adjust</button><button type="button" class="text-btn image-remove" @click="remove"><Trash2 :size="14"/>Remove</button></div></div></div>
  <input ref="input" class="sr-only" type="file" accept="image/jpeg,image/png,image/webp" :aria-label="'Choose '+imageKind" @change="choose" :disabled="readonly||working"/>
  <button v-if="!readonly&&!source" type="button" class="image-dropzone" :class="{dragging}" @click="input.click()" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop" :disabled="loading||working"><UploadCloud :size="26"/><span><strong>{{preview?'Drop a replacement here':'Drag an image here'}}</strong><small>or <span>choose a file</span> &middot; JPG, PNG, WebP &middot; up to 10 MB</small></span></button>
  <div v-if="source&&!readonly" class="friendly-crop-editor"><div class="image-editor-heading"><div><h4>Adjust your {{imageKind}}</h4><p><Move :size="13"/>Drag the image or crop handles. Pinch to zoom on touch screens.</p></div><button type="button" class="icon-btn" @click="cancelCrop" :disabled="working" aria-label="Cancel image adjustment"><X :size="18"/></button></div>
   <div class="image-crop-stage" tabindex="0" role="group" aria-label="Image crop editor. Drag to move, or use arrow keys to adjust position." @keydown="moveWithKeyboard"><Cropper ref="cropper" class="friendly-cropper" :src="source" :stencil-props="{aspectRatio:1}" :canvas="{width:512,height:512}" :resize-image="{touch:true,wheel:{ratio:.08},adjustStencil:false}" :move-image="{touch:true,mouse:true}" image-restriction="stencil" :debounce="100" @ready="ready=true" @error="error='The image editor could not load this file.'"/><span v-if="!ready" class="image-editor-loading"><LoaderCircle class="spin" :size="24"/>Opening image...</span></div>
   <div class="image-editor-toolbar" role="group" aria-label="Image adjustment tools"><button type="button" @click="cropper.zoom(1.15)" :disabled="!ready||working" aria-label="Zoom in" title="Zoom in"><ZoomIn :size="18"/><span>Zoom in</span></button><button type="button" @click="cropper.zoom(.85)" :disabled="!ready||working" aria-label="Zoom out" title="Zoom out"><ZoomOut :size="18"/><span>Zoom out</span></button><button type="button" @click="cropper.rotate(-90)" :disabled="!ready||working" aria-label="Rotate left" title="Rotate left"><RotateCcw :size="18"/><span>Left</span></button><button type="button" @click="cropper.rotate(90)" :disabled="!ready||working" aria-label="Rotate right" title="Rotate right"><RotateCw :size="18"/><span>Right</span></button><button type="button" @click="cropper.reset()" :disabled="!ready||working" title="Reset adjustments"><RefreshCw :size="17"/><span>Reset</span></button></div>
   <p v-if="isLogo" class="image-full-tip">Want to keep the whole logo? Choose <strong>Keep full image</strong> to fit it without cropping.</p><div class="image-editor-actions"><button type="button" class="text-btn" @click="input.click()" :disabled="working">Choose another</button><div><button type="button" class="btn secondary small-btn" @click="useImage(true)" :disabled="working||!originalImage">Keep full image</button><button type="button" class="btn primary small-btn" @click="useImage(false)" :disabled="working||!ready"><LoaderCircle v-if="working" class="spin" :size="15"/><Check v-else :size="15"/>{{working?'Preparing...':'Apply crop'}}</button></div></div>
  </div>
  <p v-if="error" class="form-error" role="alert">{{error}}</p>
 </section>
</template>
<style scoped>
.friendly-image-upload .photo-summary{gap:15px}.friendly-image-upload .photo-summary h3{font-size:14px;color:var(--navy)}.friendly-image-upload .photo-summary p{font-size:12px;line-height:1.7;color:#748b9c;margin:6px 0}.friendly-image-upload .company-logo-preview img{object-fit:contain;padding:6px;background:#fff}.friendly-image-upload .photo-buttons{gap:15px}.friendly-image-upload .text-btn{display:inline-flex;align-items:center;gap:5px;font-size:12px;color:#087fae}.friendly-image-upload .image-remove{color:#a36767}.image-dropzone{display:flex;align-items:center;justify-content:center;gap:15px;width:100%;min-height:96px;border:1.5px dashed #cddde8;border-radius:10px;background:#f8fbfe;color:#5796ba;text-align:left;margin-top:17px;padding:20px;transition:background .15s,border-color .15s}.image-dropzone:hover,.image-dropzone.dragging{border-color:#168dc0;background:#eef8fe}.image-dropzone>svg{flex-shrink:0}.image-dropzone strong{display:block;font-size:13px;font-weight:600;color:#476d84;line-height:1.6}.image-dropzone small{display:block;font-size:11px;line-height:1.8;color:#7e97a8;margin-top:3px}.image-dropzone small span{color:#0787b9;font-weight:600}.friendly-crop-editor{margin-top:18px;border:1px solid #dce7ef;border-radius:10px;overflow:hidden;background:#fff}.image-editor-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:15px 17px}.image-editor-heading h4{font-size:14px;color:#36596f;margin:0 0 6px}.image-editor-heading p{display:flex;align-items:center;gap:6px;margin:0;font-size:11px;color:#7d97a8;line-height:1.7}.image-editor-heading p svg{flex-shrink:0}.image-crop-stage{position:relative;background:#eef3f7;outline-offset:-3px}.friendly-cropper{height:280px;width:100%;background:#e9eff4}.image-editor-loading{display:flex;align-items:center;justify-content:center;gap:10px;position:absolute;inset:0;background:#f2f7fa;color:#7393a6;font-size:12px}.image-editor-toolbar{display:flex;align-items:center;justify-content:center;gap:5px;padding:10px;background:#f7fafc;border-top:1px solid #e4edf3;border-bottom:1px solid #e4edf3}.image-editor-toolbar button{display:flex;align-items:center;justify-content:center;gap:6px;border-radius:6px;padding:8px 10px;color:#597c92;font-size:11px;min-height:36px}.image-editor-toolbar button:hover:not(:disabled){background:#e6f3fc;color:#087fae}.image-full-tip{font-size:11px;line-height:1.8;color:#778e9d;margin:13px 17px 0}.image-full-tip strong{font-weight:600;color:#5b7c90}.image-editor-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 17px;flex-wrap:wrap}.image-editor-actions>div{display:flex;gap:9px;flex-wrap:wrap}.image-editor-actions .btn{font-size:11px;padding:9px 12px}@media(max-width:520px){.friendly-cropper{height:235px}.image-editor-heading{padding:13px}.image-editor-heading p{font-size:11px}.image-editor-toolbar{gap:2px;padding:7px 5px}.image-editor-toolbar button{flex-direction:column;gap:4px;font-size:10px;padding:7px 8px;min-width:45px}.image-editor-actions{padding:13px;gap:15px}.image-editor-actions>div{margin-left:auto}.image-dropzone{padding:16px;gap:12px}.image-dropzone small{font-size:10px}}
</style>
